def optimize_matrixbindings(out, override, replace):
    path = out / 'managed/Foster/Material.cs'
    text = path.read_text()
    text = replace(text, 'private readonly List<Uniform> uniforms = new();', 'private readonly List<Uniform> uniforms = new();\n    private object uniformEpoch = new();\n\n    protected struct MatrixUniformCache\n    {\n        internal object? Epoch;\n        internal string? Name;\n        internal bool Present;\n        internal int Start, Length;\n    }\n\n    // The cache belongs to this Material\'s current uniform layout. Clear and\n    // shader replacement create a fresh identity, including repeated clears.\n    protected unsafe void SetCachedMatrix(string name, in Matrix4x4 value, ref MatrixUniformCache cache)\n    {\n        if (cache.Epoch != uniformEpoch || cache.Name != name)\n        {\n            bool present = Shader?.Has(name) ?? false;\n            int start = 0, length = 0;\n            if (present)\n            {\n                ref readonly var binding = ref Get(name);\n                if (!IsFloat(binding.Type))\n                    throw new Exception($"Uniform \'{name}\' is not a Float value type");\n                start = binding.BufferStart;\n                length = binding.BufferLength;\n            }\n            cache = new MatrixUniformCache { Epoch = uniformEpoch, Name = name,\n                Present = present, Start = start, Length = length };\n        }\n        if (!cache.Present) return;\n        fixed (Matrix4x4* data = &value)\n            new ReadOnlySpan<float>((float*)data, Math.Min(16, cache.Length))\n                .CopyTo(floatBuffer.AsSpan()[cache.Start..]);\n    }')
    text = replace(text, 'uniforms.Clear();', 'uniforms.Clear();\n        uniformEpoch = new object();')
    path.write_text(text)
    override('Graphics/Materials.cs', [('private Matrix model;', 'private Matrix model;\n    private MatrixUniformCache mvpBinding, modelBinding;'), ('if (Shader?.Has(MatrixUniformName) ?? false)\n                Set(MatrixUniformName, value);', 'SetCachedMatrix(MatrixUniformName, value, ref mvpBinding);'), ('if (Shader?.Has("u_model") ?? false)\n                Set("u_model", value);', 'SetCachedMatrix("u_model", value, ref modelBinding);')])
